import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
protect={'進場方向':'普通訊號只多／只空／雙向；不允許的交叉或比率方向會改目標0，可退出反向舊倉。','停損比':'每次進場價加減%或點數，無移停線時生效；多只open、空high判，取open或不利跳空線成交。','啟動移停比':'入場價加減有利距離，high/low到達後啟移參考改當根open。','移停拉回比':'以當根open加減%或點數更新線，只判不同未限定有利方向；close穿新線按新線成交。','直接停利比':'入場價加減%或點數；風控第一順位，無需先有移停線。'}
